// Firecrawl bills every search result it scrapes. Read the balance first and
// refuse the whole run below the floor, naming what was seen, rather than
// discovering an empty account halfway through a row.
const FLOOR = 100;
const r = $input.first().json || {};
const d = (r.data && typeof r.data === 'object') ? r.data : r;
const cands = [d.remainingCredits, d.remaining_credits, d.credits, r.remainingCredits, r.remaining_credits];
let remaining = null;
for (const c of cands) { if (c !== undefined && c !== null && c !== '' && !isNaN(Number(c))) { remaining = Number(c); break; } }
if (remaining === null) {
  throw new Error('Refusing to research: could not read the Firecrawl balance. Keys seen: ' + (Object.keys(r).join(', ') || '(none)') + '; data keys: ' + (Object.keys(d).join(', ') || '(none)'));
}
if (remaining < FLOOR) {
  throw new Error('Refusing to research: Firecrawl has ' + remaining + ' credits left, under the floor of ' + FLOOR + '.');
}
return [{ json: { firecrawlCredits: remaining } }];

// A row needs research when the package is locked, the row is still an Idea and
// it carries no usable source. The writer skips exactly these rows (Package:
// Plan Batch in TQO FINAL V5), so this is the only way one of them moves.
const MAX_ROWS = 2;
const s = (v) => (v === null || v === undefined) ? '' : String(v).trim();
function sourcesOk(raw) {
  let list = null;
  try { list = JSON.parse(s(raw)); } catch (e) { return false; }
  return Array.isArray(list) && list.some(x => x && s(x.url) && s(x.quote));
}
const rows = $input.all().map(i => i.json)
  .filter(j => s(j.status) === 'Idea' && s(j.package_locked) && !sourcesOk(j.sources))
  .sort((a, b) => Number(a.id) - Number(b.id))
  .slice(0, MAX_ROWS);
return rows.map(j => ({ json: {
  id: j.id,
  topic: s(j.topic) || s(j.video_title),
  angle: s(j.angle),
  idea: s(j.idea),
  primary_subject: s(j.primary_subject),
  notes: s(j.notes),
  searchQuery: (s(j.primary_subject) || s(j.topic)) + ' 2026 report data -site:linkedin.com -site:instagram.com -site:facebook.com -site:tiktok.com -site:x.com -site:youtube.com'
} }));

// Search results arrive with each page's own text, fetched by Firecrawl. The
// model is handed that text and asked to copy quotes out of it. Nothing it
// returns is trusted: Quote Check below matches every quote against the same
// text character for character.
const row = $('One Row at a Time').first().json;
const r = $input.first().json || {};
const raw = Array.isArray(r.data) ? r.data : (r.data && Array.isArray(r.data.web) ? r.data.web : (Array.isArray(r.web) ? r.web : []));
const PAGE_CHARS = 8000;
const pages = [];
for (const p of raw) {
  const url = String(p.url || (p.metadata && (p.metadata.sourceURL || p.metadata.url)) || '').trim();
  const md = String(p.markdown || '').trim();
  if (!url || md.length < 200) continue;
  pages.push({ n: pages.length + 1, url: url, title: String(p.title || (p.metadata && p.metadata.title) || '').trim(), markdown: md });
}
const searchNote = r.error ? ('search error: ' + String(r.error.message || r.error).slice(0, 300)) : '';
if (!pages.length) {
  return [{ json: { id: row.id, hasPages: false, pages: [], research_note: 'No source written: the search returned no readable pages' + (searchNote ? ' (' + searchNote + ')' : '') + '. Query: ' + row.searchQuery } }];
}
const system = [
  'You extract evidence for a factual video script. You copy, you never write.',
  'From the numbered pages below, pick up to six passages that state a specific, checkable fact about the episode topic: a number, a date, a named finding or a named organisation\'s stated result.',
  'Each quote must be copied character for character from the page text, one or two sentences, between 40 and 400 characters. Do not fix typos, do not join sentences from different places, do not add or drop words.',
  'Skip any passage that cites an unnamed study, firm, survey or expert. Skip opinion, prediction and marketing copy.',
  'publisher is the organisation or person that published the page, as the page names it. If the page does not name one, skip that page.',
  'origin is the organisation that produced the figure or finding (the survey, dataset, filing or report), named exactly as the page names it. The quote must name the origin in its own words, unless the publisher itself produced the figure, in which case origin equals publisher. If the page repeats a figure without naming who produced it, skip that passage.',
  'claim is one plain sentence saying what the quote shows, adding nothing the quote does not say.',
  'Return JSON only: {"sources":[{"page":1,"publisher":"...","origin":"...","quote":"...","claim":"..."}]}. Return {"sources":[]} if nothing qualifies.'
].join(' ');
const user = 'EPISODE TOPIC: ' + row.topic + '\nANGLE: ' + row.angle + '\nIDEA: ' + row.idea + '\n\n' +
  pages.map(p => '=== PAGE ' + p.n + ' ===\nURL: ' + p.url + '\nTITLE: ' + p.title + '\nTEXT:\n' + p.markdown.slice(0, PAGE_CHARS)).join('\n\n');
const body = { model: 'gpt-oss-120b', messages: [{ role: 'system', content: system }, { role: 'user', content: user }], max_completion_tokens: 8000, reasoning_effort: 'medium', response_format: { type: 'json_object' } };
return [{ json: { id: row.id, hasPages: true, pages: pages, body: body } }];

// The mechanical check Tee approved under the doctor. A quote survives only if
// it is found, after whitespace and punctuation normalising and nothing else,
// inside the text Firecrawl fetched from that same URL. Markdown link and
// emphasis syntax is removed from both sides first, because a quote copied
// from rendered text will not carry the asterisks. It also checks provenance:
// the organisation that produced the figure must be named inside the quote,
// unless the publisher produced it, so a blog repeating an unattributed number
// cannot pass however well the model vouches for it.
const prev = $('Build Extract Prompt').first().json;
const pages = prev.pages || [];
const norm = (t) => String(t || '')
  .replace(/!\[[^\]]*\]\([^)]*\)/g, ' ')
  .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
  .replace(/[*_`]/g, '')
  .replace(/[#>|]/g, ' ')
  .replace(/[‘’‛′]/g, "'")
  .replace(/[“”‟″]/g, '"')
  .replace(/[–—−]/g, '-')
  .replace(/ /g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .toLowerCase();
let parsed = null;
const content = (((($input.first().json || {}).choices || [])[0] || {}).message || {}).content || '';
try { parsed = JSON.parse(content); } catch (e) { parsed = null; }
const offered = (parsed && Array.isArray(parsed.sources)) ? parsed.sources : [];
const checked = [];
const dropped = [];
const seen = new Set();
for (const s of offered) {
  const page = pages.find(p => p.n === Number(s.page));
  const quote = String(s.quote || '').trim();
  const why = (r) => dropped.push({ page: s.page, quote: quote.slice(0, 160), reason: r });
  if (!page) { why('no such page'); continue; }
  if (quote.length < 40 || quote.length > 400) { why('quote length ' + quote.length); continue; }
  if (!String(s.publisher || '').trim()) { why('no publisher'); continue; }
  if (!norm(page.markdown).includes(norm(quote))) { why('quote not found on the page'); continue; }
  const origin = String(s.origin || '').trim();
  if (!origin) { why('no origin named'); continue; }
  const primary = norm(origin) === norm(s.publisher);
  if (!primary && !norm(quote).includes(norm(origin))) { why('origin ' + origin + ' is not named in the quote'); continue; }
  if (!norm(page.markdown).includes(norm(origin))) { why('origin ' + origin + ' not found on the page'); continue; }
  const key = page.url + '|' + norm(quote);
  if (seen.has(key)) { why('duplicate'); continue; }
  seen.add(key);
  const quoteText = quote.replace(/!\[[^\]]*\]\([^)]*\)/g, '').replace(/\[([^\]]*)\]\([^)]*\)/g, '$1').replace(/^[\s>*-]+/, '').replace(/\s+/g, ' ').trim();
  checked.push({ url: page.url, title: page.title, publisher: String(s.publisher).trim(), origin: origin, primary: primary, quote: quote, quote_text: quoteText, claim: String(s.claim || '').trim() });
}
const note = parsed === null
  ? 'No source written: the extraction reply was not JSON.'
  : (checked.length ? '' : 'No source written: ' + offered.length + ' quote(s) offered, none survived the quote check' + (dropped.length ? ' (' + dropped.map(d => d.reason).join('; ') + ')' : '') + '.');
return [{ json: { id: prev.id, checked: checked, dropped: dropped, offered: offered.length, research_note: note } }];

// The script doctor approves or rejects each checked source. It is handed only
// the quotes that already passed the mechanical check, and it can only say yes
// or no to each: Compose Approved Sources keeps the checked text, so nothing the
// doctor writes reaches the row except its verdict and reason.
const row = $('One Row at a Time').first().json;
const list = $input.first().json.checked || [];
const system = [
  'You are the script doctor for The Quiet Operator, a calm, anti-hype channel on AI and careers. You approve the evidence a script may cite.',
  'For each numbered source decide approve or reject.',
  'Approve only when all hold: the origin is a named organisation a viewer can look up (a government agency, a research or analyst firm, a company reporting on itself, a newsroom reporting its own finding); the quote states a specific fact or a named organisation\'s published projection; the fact bears directly on the episode topic; the claim line says no more than the quote, and calls a projection a projection.',
  'Reject when the origin is a vendor, coach or app that sells the thing the figure measures, when the origin is only a blog or social post, when the figure is from an unnamed survey, or when the figure would mislead out of context. When in doubt, reject: a rejected source costs one row a day, an approved bad one goes on air in Tee\'s voice.',
  'Return JSON only: {"verdicts":[{"index":0,"verdict":"approve","reason":"..."}]} with one entry per source, index matching the list.'
].join(' ');
const user = 'EPISODE TOPIC: ' + row.topic + '\nANGLE: ' + row.angle + '\nIDEA: ' + row.idea + '\n\nSOURCES:\n' +
  list.map((s, i) => '[' + i + '] PUBLISHER: ' + s.publisher + '\nORIGIN OF THE FIGURE: ' + s.origin + (s.primary ? ' (the publisher itself)' : '') + '\nURL: ' + s.url + '\nQUOTE: "' + (s.quote_text || s.quote) + '"\nCLAIM: ' + s.claim).join('\n\n');
const body = { model: 'gpt-oss-120b', messages: [{ role: 'system', content: system }, { role: 'user', content: user }], max_completion_tokens: 4000, reasoning_effort: 'medium', response_format: { type: 'json_object' } };
return [{ json: { id: $input.first().json.id, checked: list, dropped: $input.first().json.dropped, body: body } }];

// Only checked sources the doctor approved reach the row, and each one keeps the
// exact text that passed the quote check. A doctor reply that cannot be read
// approves nothing.
const prev = $('Build Doctor Prompt').first().json;
const checked = prev.checked || [];
let parsed = null;
const content = (((($input.first().json || {}).choices || [])[0] || {}).message || {}).content || '';
try { parsed = JSON.parse(content); } catch (e) { parsed = null; }
const verdicts = (parsed && Array.isArray(parsed.verdicts)) ? parsed.verdicts : [];
const now = new Date().toISOString();
const approved = [];
const rejected = [];
checked.forEach((s, i) => {
  const v = verdicts.find(x => Number(x.index) === i);
  if (v && String(v.verdict).toLowerCase() === 'approve') approved.push({ ...s, approved_by: 'script doctor', doctor_reason: String(v.reason || '').slice(0, 300), checked_at: now });
  else rejected.push({ url: s.url, reason: v ? String(v.reason || 'rejected').slice(0, 200) : 'no verdict' });
});
const note = approved.length
  ? approved.length + ' source(s) approved on ' + now.slice(0, 10) + '; ' + rejected.length + ' rejected by the doctor; ' + (prev.dropped || []).length + ' dropped by the quote check.'
  : 'No source written: ' + checked.length + ' passed the quote check and the doctor approved none' + (parsed === null ? ' (reply was not JSON)' : '') + (rejected.length ? ': ' + rejected.map(r => r.reason).join('; ') : '') + '.';
return [{ json: { id: prev.id, sources: approved.length ? JSON.stringify(approved) : '', research_note: note.slice(0, 2000), approved: approved.length } }];
